return new AggregateRowSource<AGG_ByRegionSourceCsvRow, string, RegionSummaryAggregateRow>(
    "AGG_ByRegion",
    BuildAggregateSource(),
    row => lKP_CountryCache[row.Country].Region,
    (key, rows) => new RegionSummaryAggregateRow
